-- Schema v0. Forward-only. UUIDv7 ids are generated by the application.
-- Times are timestamptz (UTC). Money columns, when added, are bigint kobo.
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ===== Identity =====
CREATE TABLE person (
  id uuid PRIMARY KEY,
  given_name text NOT NULL,
  family_name text NOT NULL,
  middle_name text,
  date_of_birth date,                       -- required before first registration (enforced by API)
  gender text CHECK (gender IN ('male','female')),
  marital_status text,
  country text, city text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid
);
CREATE INDEX person_name_trgm ON person USING gin ((given_name || ' ' || family_name) gin_trgm_ops);

CREATE TABLE account (
  id uuid PRIMARY KEY,
  person_id uuid NOT NULL UNIQUE REFERENCES person(id),
  email citext NOT NULL UNIQUE,
  password_hash text,                       -- argon2id; null for Google-only accounts
  google_sub text UNIQUE,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','locked','disabled')),
  failed_logins int NOT NULL DEFAULT 0,
  locked_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (password_hash IS NOT NULL OR google_sub IS NOT NULL)
);

CREATE TABLE verified_contact (
  id uuid PRIMARY KEY,
  person_id uuid NOT NULL REFERENCES person(id),
  kind text NOT NULL CHECK (kind IN ('email','phone')),
  value citext NOT NULL,                    -- phone stored E.164
  verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (kind, value)
);

CREATE TABLE account_claim (
  id uuid PRIMARY KEY,
  person_id uuid NOT NULL REFERENCES person(id),
  token_hash text NOT NULL UNIQUE,          -- opaque token; only the hash is stored
  invited_email citext NOT NULL,
  state text NOT NULL DEFAULT 'CLAIM_INVITED'
    CHECK (state IN ('CLAIM_INVITED','CLAIM_VERIFIED','PROFILE_COMPLETED','EXPIRED','DECLINED','DISPUTED')),
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE session (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES account(id),
  token_hash text NOT NULL UNIQUE,
  surface text NOT NULL CHECK (surface IN ('web','admin','checkin')),
  device_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  idle_expires_at timestamptz NOT NULL,
  absolute_expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);
CREATE INDEX session_account ON session(account_id) WHERE revoked_at IS NULL;

CREATE TABLE mfa_factor (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES account(id),
  kind text NOT NULL DEFAULT 'totp' CHECK (kind = 'totp'),
  secret_encrypted bytea NOT NULL,
  confirmed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ===== Family =====
CREATE TABLE person_relationship (
  id uuid PRIMARY KEY,
  from_person_id uuid NOT NULL REFERENCES person(id),
  to_person_id uuid NOT NULL REFERENCES person(id),
  kind text NOT NULL CHECK (kind IN ('spouse','guardian_of','dependant_of','collector_for')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (from_person_id <> to_person_id),
  UNIQUE (from_person_id, to_person_id, kind)
);

CREATE TABLE guardian_authorization (
  id uuid PRIMARY KEY,
  guardian_person_id uuid NOT NULL REFERENCES person(id),
  dependant_person_id uuid NOT NULL REFERENCES person(id),
  declared_relationship text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  CHECK (guardian_person_id <> dependant_person_id)
);

CREATE TABLE authorized_collector (
  id uuid PRIMARY KEY,
  child_person_id uuid NOT NULL REFERENCES person(id),
  full_name text NOT NULL,
  relationship text NOT NULL,
  phone_encrypted bytea NOT NULL,           -- field-level encrypted
  valid_days date[],                        -- null = always
  created_by uuid NOT NULL REFERENCES person(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz
);
CREATE INDEX authorized_collector_child ON authorized_collector(child_person_id) WHERE removed_at IS NULL;

CREATE TABLE emergency_contact (
  id uuid PRIMARY KEY,
  person_id uuid NOT NULL REFERENCES person(id),
  full_name text NOT NULL,
  relationship text NOT NULL,
  phone_encrypted bytea NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ===== Catalog =====
CREATE TABLE organization (
  id uuid PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE event_template (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES organization(id),
  code text NOT NULL UNIQUE,                -- BB, SS, CP
  name text NOT NULL,
  config jsonb NOT NULL DEFAULT '{}'
);

CREATE TABLE venue (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  address text
);

CREATE TABLE event_edition (
  id uuid PRIMARY KEY,
  template_id uuid NOT NULL REFERENCES event_template(id),
  venue_id uuid REFERENCES venue(id),
  slug text NOT NULL UNIQUE,
  code text NOT NULL UNIQUE,                -- e.g. BB26
  name text NOT NULL,
  timezone text NOT NULL DEFAULT 'Africa/Lagos',
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  age_reference_date date NOT NULL,         -- default: starts_on
  camp_min_age int, camp_max_age int, camp_capacity int,
  pickup_window_start time, pickup_window_end time,
  visibility text NOT NULL DEFAULT 'draft'
    CHECK (visibility IN ('draft','preview','public','archived')),
  registration_state text NOT NULL DEFAULT 'not_open'
    CHECK (registration_state IN ('not_open','open','closed')),
  live_state text NOT NULL DEFAULT 'not_live'
    CHECK (live_state IN ('not_live','live','completed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (ends_on >= starts_on),
  CHECK (camp_min_age IS NULL OR camp_max_age IS NULL OR camp_min_age <= camp_max_age)
);

CREATE TABLE edition_capability (
  edition_id uuid NOT NULL REFERENCES event_edition(id),
  capability text NOT NULL CHECK (capability IN
    ('accommodation','daily_checkin','camp_review','studio_requests','parent_forum','paid_registration')),
  enabled boolean NOT NULL DEFAULT false,
  PRIMARY KEY (edition_id, capability)
);

CREATE TABLE event_day (
  id uuid PRIMARY KEY,
  edition_id uuid NOT NULL REFERENCES event_edition(id),
  day date NOT NULL,
  label text,
  UNIQUE (edition_id, day)
);

CREATE TABLE edition_content (
  edition_id uuid NOT NULL REFERENCES event_edition(id),
  key text NOT NULL,
  body jsonb NOT NULL,
  published_at timestamptz,
  PRIMARY KEY (edition_id, key)
);

CREATE TABLE policy_version (
  id uuid PRIMARY KEY,
  document_id text NOT NULL,                -- e.g. BB26-consent
  version int NOT NULL,
  body text NOT NULL,
  approved_at timestamptz,                  -- null blocks public launch (Q9)
  UNIQUE (document_id, version)
);

CREATE TABLE reference_counter (
  edition_id uuid PRIMARY KEY REFERENCES event_edition(id),
  last_value bigint NOT NULL DEFAULT 0
);

-- ===== Registration =====
CREATE TABLE registration (
  id uuid PRIMARY KEY,
  reference text NOT NULL UNIQUE,           -- BB26-0412-A7, generated from reference_counter
  edition_id uuid NOT NULL REFERENCES event_edition(id),
  person_id uuid NOT NULL REFERENCES person(id),
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN
    ('DRAFT','PROVISIONAL_PENDING_CLAIM','SUBMITTED','NEEDS_ACTION','CONFIRMED','COMPLETED','CANCELLED','REJECTED','EXPIRED')),
  participation_mode text NOT NULL CHECK (participation_mode IN ('day','camp','online')),
  age_on_reference_date int,                -- snapshot
  age_band text,                            -- snapshot
  draft jsonb NOT NULL DEFAULT '{}',        -- server-side wizard draft
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- One active registration per person per edition.
CREATE UNIQUE INDEX registration_one_active
  ON registration (person_id, edition_id)
  WHERE status NOT IN ('CANCELLED','REJECTED','EXPIRED');

CREATE TABLE registration_actor (
  registration_id uuid NOT NULL REFERENCES registration(id),
  person_id uuid NOT NULL REFERENCES person(id),
  role text NOT NULL CHECK (role IN ('registrant','beneficiary','guardian','sponsor','staff')),
  PRIMARY KEY (registration_id, person_id, role)
);

CREATE TABLE registration_status_history (
  id uuid PRIMARY KEY,
  registration_id uuid NOT NULL REFERENCES registration(id),
  from_status text,
  to_status text NOT NULL,
  actor_person_id uuid REFERENCES person(id),
  reason text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE invitation (
  id uuid PRIMARY KEY,
  registration_id uuid NOT NULL REFERENCES registration(id),
  invited_by uuid NOT NULL REFERENCES person(id),
  token_hash text NOT NULL UNIQUE,
  email citext NOT NULL,
  expires_at timestamptz NOT NULL,
  accepted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- Append-only history: no updates or deletes on audit-style tables.
CREATE FUNCTION forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS
$$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER registration_status_history_append_only
  BEFORE UPDATE OR DELETE ON registration_status_history
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
